# Animation v2 · C8 Kiểm thử, công cụ, giảm chuyển động (viết lại; giữ mục v1 'test' và sim animation.testclock)
# Nguồn: MainTestClock.kt @296313a4 (ui-test: frame 16 ms trên JVM; animation nhận frame time ở frame THỨ HAI sau khi bật state;
# advanceTimeBy làm tròn lên, ignoreFrameDuration; autoAdvance; trên Android test clock không điều khiển draw); "Test animations"
# (an-testing: ví dụ golden, runWithoutImplicitWait từ 1.12.0-alpha03); "Animation tooling" (an-tooling: Animation Preview);
# Essentials 40.10 (Animation Inspector, chỉ Transition); WindowRecomposer (duration scale, chương C7).

SEC_ORDER = {'c8': ['hook', 'clock', 'test', 'write', 'tooling', 'motion', 'bugs', 'exercises', 'recall']}

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    m = lambda k, vi, en=None: a('m.clockstart.' + k, vi, en)
    m('title', 'Đồng hồ test: animation bắt đầu ở frame nào', 'The test clock: on which frame an animation starts')
    m('overview', 'Bài test bật một `animateColorAsState(tween(250))` rồi tiến đồng hồ. Ba cách: tự tiến với `autoAdvance = false`; tiến `advanceTimeBy(50, ignoreFrameDuration = true)`; và để `autoAdvance = true` (mặc định). Theo dõi thời điểm đồng hồ, thời gian chơi của animation, và bài test thấy được gì.', 'The test kicks off an `animateColorAsState(tween(250))` and advances the clock. Three ways: advancing by hand with `autoAdvance = false`; `advanceTimeBy(50, ignoreFrameDuration = true)`; and leaving `autoAdvance = true` (the default). Watch the clock time, the animation\'s play time, and what the test can observe.')
    m('wrapup', 'Đồng hồ test điều khiển mọi recomposition, mọi animation và mọi LaunchedEffect. Một frame dài 16 ms trên JVM. Vì animation nhận thời điểm frame TRƯỚC recomposition, sau khi bật state phải qua hai frame thì animation mới có thời gian chơi 0. advanceTimeBy làm tròn lên bội số của frame, trừ khi bỏ làm tròn. Để autoAdvance mặc định thì việc chờ idle chạy animation tới cuối, và test chỉ thấy giá trị cuối.', 'The test clock drives every recomposition, every animation and every LaunchedEffect. A frame is 16 ms on the JVM. Because animations receive the frame time BEFORE recomposition, after flipping the state it takes two frames for the animation to reach play time 0. advanceTimeBy rounds up to a multiple of the frame unless you turn rounding off. With the default autoAdvance, waiting for idle runs the animation to its end, and the test only sees the final value.')
    m('simp.1', 'Mô hình chỉ đếm frame và thời gian chơi; nó không vẽ màu và không mô phỏng việc chờ idle chi tiết.', 'The model only counts frames and play time; it does not draw colours or simulate idle waiting in detail.')
    m('simp.2', 'Thời gian chơi ở "autoAdvance" được làm tròn tới đúng 250 ms để dễ đọc; thật ra frame cuối có thể vượt qua mốc đó.', 'The play time under "autoAdvance" is shown as exactly 250 ms for readability; in reality the last frame may overshoot that mark.')
    m('ctl.hint', 'Chạy "tự tiến" và để ý thời gian chơi vẫn là 0 sau 32 ms.', 'Run "advance by hand" and notice the play time is still 0 after 32 ms.')
    m('ctl.which', 'Cách tiến đồng hồ', 'How the clock advances')
    for k, vi, en in [('manual', 'Tự tiến (autoAdvance = false)', 'Advance by hand (autoAdvance = false)'), ('ignore', 'advanceTimeBy bỏ làm tròn', 'advanceTimeBy without rounding'), ('auto', 'autoAdvance mặc định', 'Default autoAdvance')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Bài test, đồng hồ test, Recomposer, animation', 'The test, the test clock, the Recomposer, the animation')
    m('diagramDesc', 'Bài test tiến đồng hồ; mỗi frame đồng hồ gửi thời điểm cho animation rồi cho Recomposer', 'The test advances the clock; each frame the clock sends the time to the animation, then to the Recomposer')
    for k, vi, en in [('test', 'Bài test', 'The test'), ('anim', 'Animation (tween 250 ms)', 'Animation (tween 250)')]:
        m('n.' + k, vi, en)
    m('n.clock', 'Đồng hồ test (16 ms/frame)', 'Test clock (16 ms/frame)')
    m('n.recomposer', 'Lượt recompose', 'Recomposition')
    for k, vi, en in [('clock', 'Đồng hồ (ms)', 'Clock (ms)'), ('frames', 'Frame đã tạo', 'Frames produced'), ('play', 'Thời gian chơi (ms)', 'Play time (ms)')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('auto', 'autoAdvance', 'autoAdvance'), ('play', 'Thời gian chơi', 'Play time'), ('sees', 'Test thấy', 'Test sees')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.manual', 'Tự cầm đồng hồ: autoAdvance = false', 'Holding the clock: autoAdvance = false', 'Bài test tự cầm đồng hồ: không có frame nào nếu test không tiến.', 'The test holds the clock: there are no frames unless the test advances it.'),
        ('intro.ignore', 'autoAdvance = false; sẽ gọi advanceTimeBy(50, ignoreFrameDuration = true)', 'autoAdvance = false; will call advanceTimeBy(50, ignoreFrameDuration = true)', 'Tham số `ignoreFrameDuration` tắt việc làm tròn lên bội số của frame.', 'The `ignoreFrameDuration` parameter turns off rounding up to a multiple of the frame.'),
        ('intro.auto', 'autoAdvance = true (mặc định)', 'autoAdvance = true (default)', 'Khi chờ idle, framework tự tiến đồng hồ tới khi không còn recomposition hay animation đang chờ.', 'While awaiting idleness, the framework advances the clock itself until no recomposition or animation is pending.'),
        ('toggle', 'enabled = true: chưa có gì xảy ra', 'enabled = true: nothing happens yet', 'Ghi state chỉ đánh dấu cần recompose; recomposition chỉ chạy khi đồng hồ tạo frame (trừ composition đầu tiên trong setContent).', 'Writing state only marks a recomposition as needed; recomposition only runs when the clock produces a frame (except the initial composition in setContent).'),
        ('f1', 'Frame 1 ở {clock} ms: recompose, animation được lên lịch', 'Frame 1 at {clock} ms: recompose, the animation is scheduled', 'Frame này gửi thời điểm cho animation TRƯỚC (chưa có animation nào chờ), rồi mới recompose; trong recomposition, animation được lên lịch bắt đầu. Thời gian chơi chưa có.', 'This frame sends the time to animations FIRST (none is waiting yet), then recomposes; during recomposition the animation is scheduled to start. There is no play time yet.'),
        ('f2', 'Frame 2 ở {clock} ms: animation nhận frame đầu, thời gian chơi = 0', 'Frame 2 at {clock} ms: the animation gets its first frame, play time = 0', 'Đúng ví dụ trong KDoc: bật state rồi `advanceTimeBy(32)`, thời gian chơi của animation VẪN là 0 ms.', 'Exactly the KDoc example: flip the state then `advanceTimeBy(32)`, and the animation\'s play time is STILL 0 ms.'),
        ('adv', 'advanceTimeBy(50) → tiến {adv} ms, thời gian chơi {play} ms', 'advanceTimeBy(50) → advances {adv} ms, play time {play} ms', '50 được làm tròn lên 64 (bốn frame 16 ms) để luôn tạo cùng số frame dù đồng hồ đang ở đâu.', '50 is rounded up to 64 (four 16 ms frames) so the same number of frames is always produced wherever the clock is.'),
        ('advIgnore', 'advanceTimeBy(50, ignoreFrameDuration = true): đồng hồ {clock} ms', 'advanceTimeBy(50, ignoreFrameDuration = true): clock at {clock} ms', 'Không làm tròn: đồng hồ dừng ở 50, nhưng frame chỉ có ở 16, 32, 48. KDoc: vài mili giây cuối có thể không ai thấy, vì phần lớn việc chỉ xảy ra khi có frame. Thời gian chơi {play} ms.', 'No rounding: the clock stops at 50, but frames only happen at 16, 32, 48. The KDoc: the last few milliseconds may not be observed by anyone, since most work only happens on a frame. Play time {play} ms.'),
        ('idle', 'Chờ idle: đồng hồ tự tiến tới khi animation xong', 'Awaiting idle: the clock advances until the animation ends', 'Với autoAdvance, đang có animation nghĩa là chưa idle, nên framework tiến tiếp. Khi bài test kiểm tra, animation đã ở cuối.', 'With autoAdvance, a running animation means not idle, so the framework keeps advancing. By the time the test checks, the animation is at its end.'),
        ('done.manual', 'Kiểm giá trị giữa chừng ở thời gian chơi {play} ms', 'Check the intermediate value at play time {play} ms', 'Ví dụ của tài liệu so ảnh chụp với ảnh mẫu (golden) ở đây.', 'The docs\' example compares a screenshot with a golden image here.'),
        ('done.ignore', 'Thời gian chơi {play} ms, ít hơn bạn tưởng', 'Play time {play} ms, less than you might think', 'Đồng hồ ở 50 nhưng animation mới thấy tới frame 48 (sau 2 frame khởi động). Dùng bỏ làm tròn khi thật sự cần mốc thời gian lẻ.', 'The clock is at 50 but the animation only saw up to frame 48 (after the 2 start-up frames). Turn rounding off only when you really need an odd time mark.'),
        ('done.auto', 'Test chỉ thấy giá trị cuối', 'The test only sees the final value', 'Hợp để kiểm trạng thái sau animation; không dùng được để kiểm giá trị giữa chừng.', 'Good for checking the state after the animation; useless for checking intermediate values.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('drives', 'KDoc của MainTestClock: đồng hồ này điều khiển mọi recomposition, mọi withFrameNanos (mọi animation Compose) và mọi LaunchedEffect; không tick thì animation đứng yên. [[src:ui-testclock-src]]', 'MainTestClock\'s KDoc: this clock drives all recompositions, all withFrameNanos subscribers (all Compose animations) and all LaunchedEffects; if it does not tick, animations are frozen. [[src:ui-testclock-src]]'),
        ('twoframes', 'KDoc: animation nhận thời điểm frame trước recomposition, nên không có thời điểm bắt đầu ở frame đầu sau khi bật state; với frame 16 ms, advanceTimeBy(32) vẫn để thời gian chơi ở 0. [[src:ui-testclock-src]]', 'The KDoc: animations receive the frame time before recomposition, so they do not get their start time in the first frame after flipping state; with 16 ms frames, advanceTimeBy(32) still leaves the play time at 0. [[src:ui-testclock-src]]'),
        ('round', 'KDoc: làm tròn lên bội số của frame để luôn tạo cùng số frame; frame dài 16 ms trên JVM (Android và Desktop). [[src:ui-testclock-src]] [[src:an-testing]]', 'The KDoc: rounding up to a multiple of the frame always produces the same number of frames; a frame is 16 ms on the JVM (Android and Desktop). [[src:ui-testclock-src]] [[src:an-testing]]'),
        ('auto', 'KDoc: autoAdvance mặc định là true, framework tiến đồng hồ khi chờ idle để không còn recomposition hay animation đang chờ. [[src:ui-testclock-src]]', 'The KDoc: autoAdvance is true by default; the framework advances the clock while awaiting idleness so no recompositions or animations remain pending. [[src:ui-testclock-src]]')]:
        m('co.' + k, vi, en)
    a('cap.clockstart', 'Bài test bên trái tiến đồng hồ; mỗi frame, đồng hồ gửi thời điểm cho animation trước rồi mới tới recomposition.', 'The test on the left advances the clock; each frame, the clock sends the time to the animation first and then to recomposition.')

    C = 'c8'
    a(C + '.sim.animation.clockstart', 'Animation bắt đầu ở frame nào', 'On which frame an animation starts')
    a(C + '.sim.animation.testclock', 'Lab làm tròn thời gian', 'Time rounding lab')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Test tắt `autoAdvance`, bật `enabled = true` để khởi động một `tween(250)`, rồi `advanceTimeBy(32)`. Thời gian chơi của animation lúc đó là bao nhiêu: 32 ms, 16 ms hay 0?', 'A test turns off `autoAdvance`, sets `enabled = true` to start a `tween(250)`, then calls `advanceTimeBy(32)`. What is the animation\'s play time then: 32 ms, 16 ms or 0?')
    B(C, S, 1, 'ans', '0. Frame đầu (16 ms) recompose và lên lịch animation; frame thứ hai (32 ms) mới cho animation thời điểm bắt đầu, tức thời gian chơi = 0. KDoc của `MainTestClock` dùng đúng ví dụ này, vì animation nhận thời điểm frame TRƯỚC recomposition (chương C7). [[src:ui-testclock-src]]', '0. The first frame (16 ms) recomposes and schedules the animation; only the second frame (32 ms) gives the animation its start time, i.e. play time = 0. `MainTestClock`\'s KDoc uses exactly this example, because animations receive the frame time BEFORE recomposition (chapter C7). [[src:ui-testclock-src]]')

    S = 'clock'
    a(C + '.sec.%s.title' % S, 'Đồng hồ test điều khiển những gì', 'What the test clock drives')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'KDoc của `MainTestClock` (module ui-test, commit ghim): đồng hồ này điều khiển mọi recomposition, mọi lời gọi `withFrameNanos` (tức mọi animation Compose) và mọi coroutine của `LaunchedEffect` (ví dụ nhận diện cử chỉ). Không tick thì không recompose, animation đứng yên. Đo và đặt thì tùy nền tảng: trên Android, đo và đặt chạy đồng bộ khi đồng hồ tiến, còn VẼ do Choreographer điều khiển, không theo đồng hồ test. [[src:ui-testclock-src]]', 'The KDoc of `MainTestClock` (module ui-test, pinned commit): this clock drives every recomposition, every `withFrameNanos` call (i.e. every Compose animation) and every `LaunchedEffect` coroutine (for example gesture detection). If it does not tick, nothing recomposes and animations are frozen. Measure and layout depend on the platform: on Android, measure and layout run synchronously when the clock advances, while DRAW is driven by the Choreographer, not the test clock. [[src:ui-testclock-src]]')
    B(C, S, 2, 'p', 'Ba hệ quả khi tự cầm đồng hồ (`autoAdvance = false`): (1) recomposition chỉ xảy ra khi đồng hồ tạo frame, trừ composition đầu tiên của `setContent`; (2) có cả recomposition lẫn animation đang chờ thì frame gửi thời điểm cho animation TRƯỚC, rồi mới recompose (đúng thứ tự Recomposer ở chương C7); (3) vì thế animation khởi động bằng một lần ghi state cần HAI frame mới có thời gian chơi 0. `advanceTimeBy(ms)` làm tròn lên bội số của frame (16 ms trên JVM) trừ khi `ignoreFrameDuration = true`; `advanceTimeUntil { … }` tiến từng frame tới khi điều kiện đúng. Mô phỏng ngay dưới chạy cả ba cách. [[src:ui-testclock-src]]', 'Three consequences of holding the clock yourself (`autoAdvance = false`): (1) recomposition only happens when the clock produces a frame, except the initial composition of `setContent`; (2) when both a recomposition and an animation are pending, the frame sends the time to the animation FIRST, then recomposes (the same Recomposer order as chapter C7); (3) so an animation kicked off by a state write needs TWO frames to reach play time 0. `advanceTimeBy(ms)` rounds up to a multiple of the frame (16 ms on the JVM) unless `ignoreFrameDuration = true`; `advanceTimeUntil { … }` advances frame by frame until a condition holds. The simulation just below runs all three ways. [[src:ui-testclock-src]]')

    S = 'write'
    a(C + '.sec.%s.title' % S, 'Viết test animation', 'Writing an animation test')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'kt', 'val rule = createComposeRule()\n\n@Test\nfun colorAt50ms() {\n    rule.mainClock.autoAdvance = false\n    var enabled by mutableStateOf(false)\n    rule.setContent {\n        val color by animateColorAsState(\n            if (enabled) Color.Red else Color.Green, tween(durationMillis = 250), label = "c")\n        Box(Modifier.size(64.dp).background(color))\n    }\n    enabled = true                       // khởi động animation\n    rule.mainClock.advanceTimeBy(50L)   // làm tròn lên 64; nhớ 2 frame khởi động\n    rule.onRoot().captureToImage().assertAgainstGolden()   // hàm của dự án bạn\n}', 'val rule = createComposeRule()\n\n@Test\nfun colorAt50ms() {\n    rule.mainClock.autoAdvance = false\n    var enabled by mutableStateOf(false)\n    rule.setContent {\n        val color by animateColorAsState(\n            if (enabled) Color.Red else Color.Green, tween(durationMillis = 250), label = "c")\n        Box(Modifier.size(64.dp).background(color))\n    }\n    enabled = true                       // kick off the animation\n    rule.mainClock.advanceTimeBy(50L)   // rounds up to 64; remember the 2 start-up frames\n    rule.onRoot().captureToImage().assertAgainstGolden()   // your project\'s helper\n}')
    B(C, S, 2, 'p', 'Đoạn trên theo ví dụ của trang "Test animations" (hàm so ảnh mẫu do dự án tự viết). Tài liệu thêm một API mới: khi tự tiến từng frame và kiểm giá trị giữa chừng, gọi các truy vấn trong `runWithoutImplicitWait` (trên UI thread) để bỏ các lần đồng bộ ngầm thừa và chạy test nhanh hơn; API này có từ `ui-test` 1.12.0-alpha03 và tài liệu dặn chỉ dùng cho vòng lặp tự tiến đồng hồ. Animation dùng `infiniteRepeatable` không chạy trong `ComposeTestRule` (chương IF). [[src:an-testing]] [[src:an-customize]]', 'The code above follows the "Test animations" page example (the golden comparison helper is your project\'s own). The docs add a new API: when stepping frame by frame and checking intermediate values, run the queries inside `runWithoutImplicitWait` (on the UI thread) to skip redundant implicit synchronisations and speed tests up; this API exists from `ui-test` 1.12.0-alpha03, and the docs say to use it only for manual clock-advancing loops. Animations using `infiniteRepeatable` do not run in `ComposeTestRule` (chapter IF). [[src:an-testing]] [[src:an-customize]]')

    S = 'tooling'
    a(C + '.sec.%s.title' % S, 'Công cụ: từ Animation Inspector tới Animation Preview', 'Tools: from Animation Inspector to Animation Preview')
    a(C + '.sec.%s.badge' % S, 'version')
    B(C, S, 1, 'p', 'Android Studio có công cụ "Animation Inspector": kéo dòng thời gian tới lui, chạy, lặp, đổi tốc độ, đổi hướng chuyển; nó CHỈ có khi có animation dựa trên Transition, và nhãn truyền vào `updateTransition(label = …)` thành tên tab. Tài liệu hiện tại gọi công cụ là "Animation Preview" và liệt kê nhiều API hơn: `animate*AsState`, `Crossfade`, `rememberInfiniteTransition`, `AnimatedContent`, `updateTransition`, `AnimatedVisibility`; có thể xem từng frame, xem giá trị mọi animation, chạy giữa hai trạng thái bất kỳ, phối hợp nhiều animation. Vì vậy hãy đặt `label` cho animation của bạn. Tính năng công cụ phụ thuộc phiên bản Android Studio. [[src:book-compose-ess]] [[src:an-tooling]]', 'Android Studio has an "Animation Inspector" tool: scrub the timeline back and forth, play, loop, change speed, change transition direction; it is ONLY available when a Transition-based animation is present, and the label passed to `updateTransition(label = …)` becomes the tab name. The current docs call the tool "Animation Preview" and list more APIs: `animate*AsState`, `Crossfade`, `rememberInfiniteTransition`, `AnimatedContent`, `updateTransition`, `AnimatedVisibility`; you can preview frame by frame, inspect every animation\'s values, run between any two states, and coordinate several animations. So give your animations a `label`. Tool features depend on the Android Studio version. [[src:book-compose-ess]] [[src:an-tooling]]')

    S = 'motion'
    a(C + '.sec.%s.title' % S, 'Giảm chuyển động', 'Reduced motion')
    a(C + '.sec.%s.badge' % S, 'guideline')
    B(C, S, 1, 'p', 'Phần Compose tự làm: tỉ lệ thời lượng animator của máy được đọc thành `MotionDurationScale` và áp lên mọi animation hữu hạn (bằng 0 thì nhảy tới cuối, chương C7) và animation vô hạn (bằng 0 thì nhảy tới đích rồi chờ, chương IF). Phần bạn phải làm: không để thông tin chỉ nằm trong chuyển động; thông tin quan trọng phải có ở trạng thái tĩnh; và giữ chuyển động có mục đích (chương E9 của track UI, cầu nối X6 với WCAG ở chương E10). [[src:ui-windowrecomposer]] [[src:an-suspend-src]]', 'What Compose does for you: the device\'s animator duration scale is read as a `MotionDurationScale` and applied to every finite animation (at 0 it jumps to the end, chapter C7) and infinite animation (at 0 it snaps to the target and waits, chapter IF). What you must do: do not put information only in motion; important information must exist in the static state; and keep motion purposeful (UI track chapter E9, bridge X6 to WCAG in chapter E10). [[src:ui-windowrecomposer]] [[src:an-suspend-src]]')
    B(C, S, 2, 'note', 'Kiểm thử chế độ này: bật tỉ lệ thời lượng animator = 0 trong tùy chọn nhà phát triển trên máy thật và đi qua các luồng chính; mọi màn hình phải vẫn hiểu được ở trạng thái cuối.', 'Testing this mode: set the animator duration scale to 0 in developer options on a real device and walk through the main flows; every screen must still make sense in its final state.')
    B(C, S, 2, 'kind', 'try')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Test giữa chừng luôn so được ảnh của frame ĐẦU, dù đã advanceTimeBy(32).', 'An intermediate test always matches the FIRST frame\'s image even after advanceTimeBy(32).')
    B(C, S, 1, 'cause', 'Hai frame đầu sau khi bật state chỉ để recompose và khởi động; thời gian chơi vẫn là 0.', 'The first two frames after flipping state only recompose and start up; play time is still 0.')
    B(C, S, 1, 'fix', 'Tính thêm hai frame khởi động (32 ms) vào mốc cần kiểm, hoặc dùng `advanceTimeUntil { … }`. [[src:ui-testclock-src]]', 'Add the two start-up frames (32 ms) to the mark you check, or use `advanceTimeUntil { … }`. [[src:ui-testclock-src]]')
    B(C, S, 2, 'bug', 'Test kiểm giá trị giữa chừng nhưng luôn thấy giá trị cuối.', 'A test checks an intermediate value but always sees the final value.')
    B(C, S, 2, 'cause', '`autoAdvance` vẫn là true: mỗi lần chờ idle (kể cả trong truy vấn node) đồng hồ chạy tới khi animation xong.', '`autoAdvance` is still true: each idle wait (including inside node queries) runs the clock until the animation ends.')
    B(C, S, 2, 'fix', 'Đặt `rule.mainClock.autoAdvance = false` trước khi khởi động animation. [[src:an-testing]] [[src:ui-testclock-src]]', 'Set `rule.mainClock.autoAdvance = false` before kicking off the animation. [[src:an-testing]] [[src:ui-testclock-src]]')
    B(C, S, 3, 'bug', 'Trên Android, `advanceTimeUntil { ảnh đã đổi }` hết thời gian chờ.', 'On Android, `advanceTimeUntil { the image changed }` times out.')
    B(C, S, 3, 'cause', 'KDoc: trên Android, việc vẽ không chạy giữa các lần tiến đồng hồ; điều kiện dựa vào kết quả vẽ sẽ không bao giờ đúng.', 'The KDoc: on Android, draw does not run between clock advancements; a condition relying on draw results never becomes true.')
    B(C, S, 3, 'fix', 'Dùng điều kiện dựa trên state hay semantics, hoặc `waitUntil` như KDoc gợi ý. [[src:ui-testclock-src]]', 'Use a condition based on state or semantics, or `waitUntil` as the KDoc suggests. [[src:ui-testclock-src]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Viết test kiểm `AnimatedVisibility` đã ẩn xong nội dung (node không còn tồn tại) sau khi đặt visible = false.', 'Write a test checking that `AnimatedVisibility` has finished hiding its content (the node no longer exists) after setting visible = false.')
    B(C, S, 1, 'hint', 'Không cần giá trị giữa chừng: để autoAdvance mặc định.', 'You do not need intermediate values: keep the default autoAdvance.')
    B(C, S, 1, 'solkt', 'rule.setContent { AnimatedVisibility(visible) { Text("Banner", Modifier.testTag("banner")) } }\nvisible = false\nrule.onNodeWithTag("banner").assertDoesNotExist()   // chờ idle chạy exit tới cuối', 'rule.setContent { AnimatedVisibility(visible) { Text("Banner", Modifier.testTag("banner")) } }\nvisible = false\nrule.onNodeWithTag("banner").assertDoesNotExist()   // the idle wait runs the exit to the end')
    B(C, S, 1, 'sol', 'Với autoAdvance, truy vấn node chờ idle, tức chạy exit tới khi xong; theo chương C4, nội dung chỉ bị gỡ sau khi exit xong, nên lúc đó node không còn.', 'With autoAdvance, the node query waits for idle, i.e. runs the exit until it ends; per chapter C4, the content is only removed after the exit finishes, so by then the node is gone.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Sau khi bật state, cần mấy frame để animation có thời gian chơi 0, và vì sao?', 'After flipping state, how many frames until the animation reaches play time 0, and why?')
    B(C, S, 1, 'ans', 'Hai: frame 1 recompose và lên lịch animation; frame 2 cho animation thời điểm bắt đầu (animation nhận frame trước recomposition).', 'Two: frame 1 recomposes and schedules the animation; frame 2 gives it its start time (animations get the frame before recomposition).')
    B(C, S, 2, 'ask', 'Trên Android, tiến đồng hồ test có làm phase vẽ chạy không?', 'On Android, does advancing the test clock run the draw phase?')
    B(C, S, 2, 'ans', 'Không; đo và đặt chạy, còn vẽ do Choreographer điều khiển.', 'No; measure and layout run, while draw is driven by the Choreographer.')
    for q, qv, qe, av, ae, wv, we in [
        ('q3', 'advanceTimeBy(50, ignoreFrameDuration = true) có tạo frame ở 50 ms không?', 'Does advanceTimeBy(50, ignoreFrameDuration = true) produce a frame at 50 ms?', 'Không.', 'No.', 'Frame chỉ ở bội số 16 ms; vài mili giây cuối có thể không ai thấy.', 'Frames only occur at multiples of 16 ms; the last few milliseconds may go unobserved.'),
        ('q4', 'Animation Preview hiện tại hỗ trợ animate*AsState không?', 'Does the current Animation Preview support animate*AsState?', 'Có.', 'Yes.', 'Tài liệu tooling liệt kê nó; Animation Inspector thời Essentials chỉ cho Transition.', 'The tooling docs list it; the Animation Inspector in the Essentials era was Transition-only.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)

